<section class="section"><h3>01 · Identificación de la orden</h3><div class="info"><div><small>Orden de producción</small><strong>{{ $production_order->number }}</strong></div><div><small>Producto / SKU</small><strong>{{ $production_order->product->nombre??'—' }} / {{ $production_order->product->sku??'—' }}</strong></div><div><small>Materia prima principal</small><strong>{{ $production_order->rawMaterial->name??'—' }}</strong></div><div><small>Consumo registrado</small><strong>{{ number_format((float)$production_order->consumed_quantity,2) }} {{ $production_order->rawMaterial->unit??'' }}</strong></div><div><small>Inicio</small><strong>{{ $production_order->started_at?->format('d/m/Y H:i')??'—' }}</strong></div><div><small>Finalización</small><strong>{{ $production_order->finished_at?->format('d/m/Y H:i')??'—' }}</strong></div><div><small>Responsable que creó la orden</small><strong>{{ $production_order->user->name??'—' }}</strong></div><div><small>Tiempo estándar por unidad</small><strong>{{ number_format($standard,3) }} segundos</strong></div></div></section>
<section class="section"><h3>02 · Análisis de rendimiento</h3><div class="analysis"><div class="metric"><small>Diferencia real vs. teórica</small><strong>{{ ($actualQuantity-$theoretical)>=0?'+':'' }}{{ number_format($actualQuantity-$theoretical,2) }}</strong></div><div class="metric"><small>Cumplimiento del objetivo</small><strong>{{ $production_order->target_quantity>0?number_format($actualQuantity/$production_order->target_quantity*100,1):'0.0' }}%</strong></div><div class="metric"><small>Tiempo promedio real / unidad</small><strong>{{ number_format($actualPerUnit,2) }} s</strong></div></div><p class="sub" style="line-height:1.5;margin-top:9px">La producción teórica se obtiene dividiendo el tiempo efectivo acumulado entre el tiempo estándar por unidad. La diferencia compara las unidades reales registradas con esa referencia teórica. El cumplimiento compara la producción real con la cantidad objetivo.</p></section>
<section class="section"><h3>03 · Detalle de jornadas</h3><table class="table"><thead><tr><th>Jornada</th><th>Inicio / cierre</th><th>Personal participante</th><th>Unidades reales</th><th>Tiempo efectivo</th><th>Promedio / unidad</th></tr></thead><tbody>@foreach($production_order->shifts as $shift)@php $secs=(int)$shift->actual_duration_seconds;$qty=(float)$shift->produced_quantity;@endphp<tr><td>#{{ $shift->shift_number }}</td><td>{{ $shift->started_at->format('d/m/Y H:i') }}<br>{{ $shift->ended_at?->format('d/m/Y H:i')??'—' }}</td><td>{{ $shift->workers->pluck('name')->join(', ') }}</td><td>{{ number_format($qty,2) }}</td><td>{{ gmdate('H:i:s',$secs) }}</td><td>{{ $qty>0?number_format($secs/$qty,2).' s':'—' }}</td></tr>@if($shift->pauses->count())<tr><td colspan="6" style="color:#64748b">Pausas: @foreach($shift->pauses as $pause){{ $pause->paused_at->format('H:i') }}–{{ $pause->resumed_at?->format('H:i')??'—' }}{{ $pause->reason?' ('.$pause->reason.')':'' }}@if(!$loop->last); @endif @endforeach</td></tr>@endif @if($shift->notes)<tr><td colspan="6"><strong>Observación:</strong> {{ $shift->notes }}</td></tr>@endif @endforeach</tbody></table></section>
